//! `ProteinData` over a bundled slice of human proteins.
//!
//! `resources/protein_data.tsv.gz` (regenerated by
//! `scripts/gen_protein_data.py`) holds every reviewed human UniProtKB entry
//! annotated with the Gene Ontology term "actin binding" or one of its
//! descendants: the HGNC gene symbol (the standard name), the HGNC approved
//! name, the canonical amino acid sequence and the GO annotations.
//!
//! As in Wolfram's `ProteinData`, the protein classes are GO terms, named by
//! camel-casing the term name (`"actin binding"` is `"ActinBinding"`), and a
//! class holds the proteins annotated directly with its term.

use super::*;
use crate::functions::list_helpers_ast::wolfram_string_order;
use std::collections::HashMap;
use std::sync::LazyLock;

struct Protein {
  symbol: String,
  name: String,
  sequence: String,
  /// Indices into `ProteinTable::terms` per GO aspect.
  functions: Vec<usize>,
  processes: Vec<usize>,
  components: Vec<usize>,
}

struct Term {
  class: String,
  name: String,
}

struct ProteinTable {
  /// Sorted by standard name in canonical order.
  proteins: Vec<Protein>,
  terms: Vec<Term>,
  /// Class name to term index.
  classes: HashMap<String, usize>,
}

fn wl_cmp(a: &str, b: &str) -> std::cmp::Ordering {
  0.cmp(&wolfram_string_order(a, b))
}

/// The class name of a GO term: each word capitalized, punctuation and
/// spaces dropped (`"Arp2/3 complex binding"` is `"Arp23ComplexBinding"`).
fn class_name(term: &str) -> String {
  term
    .split(|c: char| !c.is_alphanumeric())
    .filter(|w| !w.is_empty())
    .map(|w| {
      let mut cs = w.chars();
      let first = cs.next().unwrap();
      first.to_uppercase().chain(cs).collect::<String>()
    })
    .collect()
}

static TABLE: LazyLock<ProteinTable> = LazyLock::new(|| {
  use flate2::read::GzDecoder;
  use std::io::Read;
  let compressed = include_bytes!("../../resources/protein_data.tsv.gz");
  let mut text = String::new();
  GzDecoder::new(&compressed[..])
    .read_to_string(&mut text)
    .expect("protein_data.tsv.gz is valid gzip");

  let mut terms = Vec::new();
  let mut term_index: HashMap<&str, usize> = HashMap::new();
  for line in text.lines() {
    let f: Vec<&str> = line.split('\t').collect();
    if f.len() == 3 && f[0] == "T" {
      term_index.insert(f[1], terms.len());
      terms.push(Term {
        class: class_name(f[2]),
        name: f[2].to_string(),
      });
    }
  }
  // Annotations are kept in the canonical order of their class names, so a
  // property's class list and its `"Name"` list line up.
  let ids = |s: &str| -> Vec<usize> {
    let mut v: Vec<usize> = s
      .split(',')
      .filter_map(|id| term_index.get(id).copied())
      .collect();
    v.sort_by(|&a, &b| wl_cmp(&terms[a].class, &terms[b].class));
    v.dedup_by(|a, b| terms[*a].class == terms[*b].class);
    v
  };
  let mut proteins: Vec<Protein> = text
    .lines()
    .filter_map(|line| {
      let f: Vec<&str> = line.split('\t').collect();
      if f.len() != 7 || f[0] != "P" {
        return None;
      }
      Some(Protein {
        symbol: f[1].to_string(),
        name: f[2].to_string(),
        sequence: f[3].to_string(),
        functions: ids(f[4]),
        processes: ids(f[5]),
        components: ids(f[6]),
      })
    })
    .collect();
  proteins.sort_by(|a, b| wl_cmp(&a.symbol, &b.symbol));

  let mut classes = HashMap::new();
  for (i, t) in terms.iter().enumerate() {
    classes.entry(t.class.clone()).or_insert(i);
  }
  ProteinTable {
    proteins,
    terms,
    classes,
  }
});

const PROPERTIES: &[&str] = &[
  "BiologicalProcesses",
  "CellularComponents",
  "MolecularFunctions",
  "Name",
  "Sequence",
  "SequenceLength",
  "StandardName",
];

fn find(spec: &Expr) -> Option<&'static Protein> {
  let name = match spec {
    Expr::String(s) => s.as_str(),
    Expr::FunctionCall { name, args }
      if name == "Entity"
        && args.len() == 2
        && matches!(&args[0], Expr::String(t) if t == "Protein") =>
    {
      match &args[1] {
        Expr::String(s) => s.as_str(),
        _ => return None,
      }
    }
    _ => return None,
  };
  TABLE.proteins.iter().find(|p| p.symbol == name)
}

fn strings<'a>(items: impl Iterator<Item = &'a str>) -> Expr {
  Expr::List(items.map(str_expr).collect::<Vec<_>>().into())
}

/// The proteins annotated directly with the class's GO term.
fn class_members(class: &str) -> Option<Expr> {
  let t = &TABLE;
  let idx = *t.classes.get(class)?;
  let class = &t.terms[idx].class;
  let has = |v: &[usize]| v.iter().any(|&i| &t.terms[i].class == class);
  Some(strings(
    t.proteins
      .iter()
      .filter(|p| has(&p.functions) || has(&p.processes) || has(&p.components))
      .map(|p| p.symbol.as_str()),
  ))
}

fn go_list(p: &'static Protein, prop: &str) -> Option<&'static [usize]> {
  match prop {
    "BiologicalProcesses" => Some(&p.processes),
    "CellularComponents" => Some(&p.components),
    "MolecularFunctions" => Some(&p.functions),
    _ => None,
  }
}

fn property(p: &'static Protein, prop: &str) -> Expr {
  match prop {
    "Name" => str_expr(&p.name),
    "StandardName" => str_expr(&p.symbol),
    "Sequence" => str_expr(&p.sequence),
    "SequenceLength" => Expr::Integer(p.sequence.chars().count() as i128),
    _ => match go_list(p, prop) {
      Some(ids) => strings(ids.iter().map(|&i| TABLE.terms[i].class.as_str())),
      None => call1("Missing", str_expr("NotAvailable")),
    },
  }
}

/// `ProteinData[p, prop, "Name"]`: the GO term names behind a class list.
fn property_names(p: &'static Protein, prop: &str) -> Expr {
  match go_list(p, prop) {
    Some(ids) => strings(ids.iter().map(|&i| TABLE.terms[i].name.as_str())),
    None => call1("Missing", str_expr("NotAvailable")),
  }
}

fn notent(spec: &Expr) {
  crate::emit_message(&format!(
    "ProteinData::notent: {} is not a known entity, class, or tag for \
     ProteinData. Use ProteinData[] for a list of entities.",
    match spec {
      Expr::String(s) => s.clone(),
      other => crate::syntax::expr_to_output(other),
    }
  ));
}

pub fn protein_data_ast(args: &[Expr]) -> Result<Expr, InterpreterError> {
  let t = &*TABLE;
  match args {
    [] => Ok(strings(t.proteins.iter().map(|p| p.symbol.as_str()))),
    [Expr::Identifier(s)] if s == "All" => {
      Ok(strings(t.proteins.iter().map(|p| p.symbol.as_str())))
    }
    [Expr::String(s)] if s == "Properties" => {
      Ok(strings(PROPERTIES.iter().copied()))
    }
    [Expr::String(s)] if s == "Classes" => {
      let mut names: Vec<&str> = t.classes.keys().map(String::as_str).collect();
      names.sort_by(|a, b| wl_cmp(a, b));
      Ok(strings(names.into_iter()))
    }
    [Expr::String(s)] if find(&args[0]).is_none() => {
      if let Some(list) = class_members(s) {
        Ok(list)
      } else {
        notent(&args[0]);
        Ok(unevaluated("ProteinData", args))
      }
    }
    // A list of proteins maps over its elements.
    [Expr::List(items), rest @ ..] if !rest.is_empty() => {
      let mut out = Vec::with_capacity(items.len());
      for item in items {
        let mut a = vec![item.clone()];
        a.extend_from_slice(rest);
        out.push(protein_data_ast(&a)?);
      }
      Ok(Expr::List(out.into()))
    }
    [spec, Expr::String(prop)] => {
      if let Some(p) = find(spec) {
        Ok(property(p, prop))
      } else {
        notent(spec);
        Ok(unevaluated("ProteinData", args))
      }
    }
    [spec, Expr::String(prop), Expr::String(ann)] if ann == "Name" => {
      if let Some(p) = find(spec) {
        Ok(property_names(p, prop))
      } else {
        notent(spec);
        Ok(unevaluated("ProteinData", args))
      }
    }
    _ => Ok(unevaluated("ProteinData", args)),
  }
}

#[cfg(test)]
mod tests {
  use super::class_name;

  #[test]
  fn camel_cases_go_terms() {
    assert_eq!(class_name("actin binding"), "ActinBinding");
    assert_eq!(class_name("Arp2/3 complex binding"), "Arp23ComplexBinding");
    assert_eq!(class_name("mRNA binding"), "MRNABinding");
  }
}
